from .money import MAX_CENTS, amount_to_cents, cents_to_decimal, format_amount


def make_invoice(amounts):
    items = list(amounts)  # copy; never mutate the caller's sequence
    total = 0
    for item in items:
        total += amount_to_cents(item)
    if total > MAX_CENTS:
        raise ValueError("invoice total exceeds 1000000.00")
    return {"total": format_amount(cents_to_decimal(total)), "count": len(items)}
